    parts = s.split(';')
    for part in parts:
        if '=' in part:
            key, value = part.split('=', 1)
            key = key.strip()
            # Handle escaped semicolons like \\; inside a value
            value = value.replace('\\;', '.;')
            result[key.strip()] = value.strip()
    return result
